import type {
  EchoTextBurst,
  EchoTextDirection,
  EchoTextEase,
  EchoTextEngineOptions,
  EchoTextVector,
} from './types';

export const clamp = (value: number, min: number, max: number): number =>
  Math.min(Math.max(value, min), max);

const directionVectors: Record<EchoTextDirection, EchoTextVector> = {
  right: { x: 1, y: 0 },
  left: { x: -1, y: 0 },
  up: { x: 0, y: -1 },
  down: { x: 0, y: 1 },
  diagonal: { x: 0.72, y: 0.72 },
};

const easing: Record<EchoTextEase, (t: number) => number> = {
  linear: (t) => t,
  'ease-out': (t) => 1 - Math.pow(1 - t, 3),
  'ease-in-out': (t) =>
    t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2,
  snappy: (t) => 1 - Math.pow(1 - t, 5),
};

const DRIFT_PERIOD = 7200;
const DRIFT_IDLE = 2600;
const BURST_LIFE = 1100;
const BURST_GAP = 80;

const readScroll = (target: Document | Element): [number, number] =>
  target instanceof Element
    ? [target.scrollLeft || 0, target.scrollTop || 0]
    : [window.scrollX, window.scrollY];

/** Starts the echo animation loop. Returns a teardown function. */
export function setupEchoText(options: EchoTextEngineOptions): () => void {
  const { root, burstLayer, copies, echoCount, direction, mode, trail } =
    options;

  const vector = directionVectors[direction] ?? directionVectors.right;
  const safeOffset = clamp(Number(options.offset) || 0, 0, 120);
  const safeCursorRadius = clamp(Number(options.cursorRadius) || 320, 40, 1200);
  const safeLag = clamp(Number(options.lag) || 0.16, 0.02, 0.5);
  const safeFade = clamp(Number(options.fade) || 0.64, 0.1, 0.95);
  const safeBlur = clamp(Number(options.blur) || 0, 0, 16);
  const safeScale = clamp(Number(options.echoScale) || 1, 0.25, 2.5);
  const safeDuration = Math.max(0, Number(options.duration) || 0);
  const easeFn = easing[options.ease] ?? easing['ease-out'];
  const entranceEnabled = mode === 'entrance' || mode === 'both';
  const liveEnabled = mode === 'pointer' || mode === 'both';
  const canHover = window.matchMedia(
    '(hover: hover) and (pointer: fine)',
  ).matches;
  const drifting = liveEnabled && trail === 'auto';
  const scrolling = liveEnabled && trail === 'scroll';
  const following = liveEnabled && canHover && !scrolling;
  const driftSpacing = 0.12 + safeLag * 1.1;
  const burstReach = clamp(safeOffset / 36, 0.35, 2.5);
  const shiftLimit = safeOffset * 4;

  const initialBursts: EchoTextBurst[] = [];
  const state = {
    targetX: 0,
    targetY: 0,
    lastTargetX: 0,
    lastTargetY: 0,
    activity: entranceEnabled ? 1 : 0,
    positions: Array.from({ length: echoCount + 1 }, (_, index) => {
      const entranceAmount = entranceEnabled ? safeOffset * (index + 0.35) : 0;
      return { x: vector.x * entranceAmount, y: vector.y * entranceAmount };
    }),
    bends: Array.from({ length: echoCount + 1 }, () => ({ x: 0, y: 0 })),
    startTime: performance.now(),
    lastTime: 0,
    drift: 0,
    phase: 0,
    pointerNear: false,
    pointerTime: -Infinity,
    visible: true,
    pushX: 0,
    pushY: 0,
    velocityX: 0,
    velocityY: 0,
    bursts: initialBursts,
  };
  let frame = 0;

  for (let index = 1; index <= echoCount; index += 1) {
    const copy = copies[index];
    if (copy)
      copy.style.filter =
        safeBlur > 0
          ? `blur(${((safeBlur * index) / echoCount).toFixed(2)}px)`
          : 'none';
  }

  const renderBursts = (now: number): void => {
    state.bursts = state.bursts.filter((burst) => {
      const age = now - burst.start;
      let alive = false;

      burst.nodes.forEach((node, index) => {
        const local = (age - index * BURST_GAP) / BURST_LIFE;
        if (local < 1) alive = true;

        const progress = clamp(local, 0, 1);
        const spread = 1 - Math.pow(1 - progress, 3);
        const scale = 1 + spread * 0.34 * burstReach;
        const peak = 0.75 * Math.pow(safeFade, index * 0.5);
        const opacity =
          local <= 0
            ? 0
            : Math.min(1, progress * 8) * Math.pow(1 - progress, 1.5) * peak;

        node.style.transform = `translate3d(${burst.x.toFixed(2)}px, ${burst.y.toFixed(2)}px, 0) scale(${scale.toFixed(4)})`;
        node.style.opacity = opacity.toFixed(3);
        node.style.filter =
          safeBlur > 0
            ? `blur(${(safeBlur * 0.3 * spread).toFixed(2)}px)`
            : 'none';
      });

      if (!alive) for (const node of burst.nodes) node.remove();
      return alive;
    });
  };

  function renderFrame(now: number): void {
    frame = 0;

    const dt = state.lastTime ? clamp(now - state.lastTime, 0, 64) : 16.67;
    const step = dt / 16.67;
    state.lastTime = now;

    const elapsed = now - state.startTime;
    const entranceProgress =
      entranceEnabled && safeDuration > 0
        ? clamp(elapsed / safeDuration, 0, 1)
        : 1;
    const entranceRest = entranceEnabled ? 1 - easeFn(entranceProgress) : 0;
    const targetVelocity = Math.hypot(
      state.targetX - state.lastTargetX,
      state.targetY - state.lastTargetY,
    );

    state.lastTargetX = state.targetX;
    state.lastTargetY = state.targetY;

    if (drifting) {
      const away =
        !following ||
        !state.pointerNear ||
        now - state.pointerTime > DRIFT_IDLE;
      state.drift +=
        ((away ? 1 : 0) - state.drift) * (1 - Math.pow(0.965, step));
      state.phase += (dt / DRIFT_PERIOD) * Math.PI * 2;
    }

    if (scrolling) {
      const blend = 1 - Math.pow(0.7, step);
      state.velocityX +=
        (state.pushX / Math.max(step, 0.25) - state.velocityX) * blend;
      state.velocityY +=
        (state.pushY / Math.max(step, 0.25) - state.velocityY) * blend;
      state.pushX = 0;
      state.pushY = 0;
    }

    const speed = Math.hypot(state.velocityX, state.velocityY);
    const shiftX = clamp(-state.velocityX * 3.2, -shiftLimit, shiftLimit);
    const shiftY = clamp(-state.velocityY * 3.2, -shiftLimit, shiftLimit);
    const followX = state.targetX * (1 - state.drift);
    const followY = state.targetY * (1 - state.drift);

    let maxSeparation = 0;
    let maxGap = 0;

    for (let index = 0; index <= echoCount; index += 1) {
      const copy = copies[index];
      const current = state.positions[index];
      const bend = state.bends[index];
      if (!copy || !current || !bend) continue;

      const depth = echoCount ? index / echoCount : 0;
      const entranceAmount = entranceRest * safeOffset * (index + 0.35);
      let desiredX = followX + vector.x * entranceAmount;
      let desiredY = followY + vector.y * entranceAmount;

      if (state.drift > 0.0005) {
        const phase = state.phase - index * driftSpacing;
        const swing = safeOffset * state.drift * (0.25 + 0.75 * depth);
        desiredX += Math.sin(phase) * swing;
        desiredY += Math.sin(phase) * Math.cos(phase) * swing * 1.3;
      }

      const lerp =
        1 -
        Math.pow(
          1 - clamp(0.34 / (1 + index * safeLag * 4.2), 0.018, 0.36),
          step,
        );
      const bendLerp =
        1 - Math.pow(1 - 0.3 / (1 + depth * (1 + safeLag * 8)), step);

      current.x += (desiredX - current.x) * lerp;
      current.y += (desiredY - current.y) * lerp;
      bend.x += (shiftX * depth - bend.x) * bendLerp;
      bend.y += (shiftY * depth - bend.y) * bendLerp;
      maxGap = Math.max(
        maxGap,
        Math.abs(desiredX - current.x),
        Math.abs(desiredY - current.y),
        Math.abs(shiftX * depth - bend.x),
        Math.abs(shiftY * depth - bend.y),
      );

      const x = current.x + bend.x;
      const y = current.y + bend.y;
      const scale = 1 + (safeScale - 1) * depth;
      copy.style.transform = `translate3d(${x.toFixed(3)}px, ${y.toFixed(3)}px, 0) scale(${scale.toFixed(4)})`;

      const front = state.positions[0];
      if (index > 0 && front) {
        maxSeparation = Math.max(
          maxSeparation,
          Math.hypot(x - front.x, y - front.y),
        );
      }
    }

    const separationActivity =
      safeOffset > 0 ? clamp(maxSeparation / (safeOffset * 2.25), 0, 1) : 0;
    const targetActivity =
      safeOffset > 0 ? clamp(targetVelocity / (safeOffset * 0.35), 0, 1) : 0;
    const nextActivity = Math.max(
      entranceRest,
      separationActivity,
      targetActivity,
      state.drift * 0.9,
      clamp(speed / 5, 0, 1),
    );
    state.activity +=
      (nextActivity - state.activity) * (1 - Math.pow(0.82, step));

    renderBursts(now);

    const running =
      entranceProgress < 1 ||
      state.activity > 0.002 ||
      maxGap > 0.05 ||
      speed > 0.02 ||
      state.bursts.length > 0 ||
      (drifting && state.visible);
    if (!running) state.activity = 0;

    for (let index = 1; index <= echoCount; index += 1) {
      const copy = copies[index];
      if (copy)
        copy.style.opacity = String(Math.pow(safeFade, index) * state.activity);
    }

    if (running) frame = requestAnimationFrame(renderFrame);
  }

  const wake = (): void => {
    if (!frame) {
      state.lastTime = 0;
      frame = requestAnimationFrame(renderFrame);
    }
  };

  const handlePointerMove = (event: PointerEvent): void => {
    const rect = root.getBoundingClientRect();
    if (!rect.width || !rect.height) return;

    const deltaX = event.clientX - (rect.left + rect.width / 2);
    const deltaY = event.clientY - (rect.top + rect.height / 2);
    const distance = Math.hypot(deltaX, deltaY);
    const reach = distance > 0 ? clamp(distance / safeCursorRadius, 0, 1) : 0;
    const dirX = distance > 0 ? deltaX / distance : 0;
    const dirY = distance > 0 ? deltaY / distance : 0;

    state.targetX = dirX * reach * safeOffset;
    state.targetY = dirY * reach * safeOffset * 0.72;
    state.pointerNear = distance <= safeCursorRadius;
    state.pointerTime = performance.now();
    wake();
  };

  const handlePointerOut = (event: PointerEvent): void => {
    if (event.relatedTarget) return;
    state.targetX = 0;
    state.targetY = 0;
    state.pointerNear = false;
    wake();
  };

  const scrollMemory = new WeakMap<Document | Element, [number, number]>();

  const handleScroll = (event: Event): void => {
    const target = event.target;
    let source: Document | Element | null = null;
    if (target instanceof Document) source = target;
    else if (target instanceof Element && target.contains(root))
      source = target;
    if (!source) return;

    const [x, y] = readScroll(source);
    const last = scrollMemory.get(source);
    scrollMemory.set(source, [x, y]);
    if (!last) return;

    state.pushX -= x - last[0];
    state.pushY -= y - last[1];
    wake();
  };

  const handleClick = (event: MouseEvent): void => {
    const rect = root.getBoundingClientRect();
    if (!burstLayer || !echoCount || !rect.width || !rect.height) return;

    const originX = clamp((event.clientX - rect.left) / rect.width, 0, 1) * 100;
    const originY = clamp((event.clientY - rect.top) / rect.height, 0, 1) * 100;
    const count = clamp(Math.round(echoCount / 3) + 2, 3, 6);
    const front = state.positions[0];
    const nodes: HTMLElement[] = [];

    for (let index = 0; index < count; index += 1) {
      const source =
        copies[
          1 + Math.round((index / Math.max(1, count - 1)) * (echoCount - 1))
        ];
      if (!source) continue;
      const node = source.cloneNode(true);
      if (!(node instanceof HTMLElement)) continue;
      node.removeAttribute('data-echo-index');
      node.style.transformOrigin = `${originX.toFixed(1)}% ${originY.toFixed(1)}%`;
      node.style.opacity = '0';
      burstLayer.appendChild(node);
      nodes.push(node);
    }

    state.bursts.push({
      start: performance.now(),
      x: front?.x || 0,
      y: front?.y || 0,
      nodes,
    });
    while (state.bursts.length > 4) {
      const old = state.bursts.shift();
      if (old) for (const node of old.nodes) node.remove();
    }
    wake();
  };

  if (following) {
    window.addEventListener('pointermove', handlePointerMove, {
      passive: true,
    });
    document.addEventListener('pointerout', handlePointerOut);
  }

  if (scrolling) {
    scrollMemory.set(document, readScroll(document));
    for (let node = root.parentElement; node; node = node.parentElement)
      scrollMemory.set(node, readScroll(node));
    document.addEventListener('scroll', handleScroll, {
      capture: true,
      passive: true,
    });
  }

  if (options.clickBurst) root.addEventListener('click', handleClick);

  let observer: IntersectionObserver | undefined;
  if (drifting) {
    observer = new IntersectionObserver((entries) => {
      const entry = entries.at(-1);
      state.visible = entry ? entry.isIntersecting : true;
      if (state.visible) wake();
    });
    observer.observe(root);
  }

  renderFrame(state.startTime);

  return () => {
    cancelAnimationFrame(frame);
    window.removeEventListener('pointermove', handlePointerMove);
    document.removeEventListener('pointerout', handlePointerOut);
    document.removeEventListener('scroll', handleScroll, { capture: true });
    root.removeEventListener('click', handleClick);
    observer?.disconnect();
    for (const burst of state.bursts)
      for (const node of burst.nodes) node.remove();
  };
}

export { default as EchoText } from './EchoText.vue';
export type {
  EchoTextDirection,
  EchoTextEase,
  EchoTextMode,
  EchoTextProps,
  EchoTextStyle,
  EchoTextTrail,
} from './types';

export type EchoTextDirection = 'right' | 'left' | 'up' | 'down' | 'diagonal';
export type EchoTextMode = 'entrance' | 'pointer' | 'both';
export type EchoTextTrail = 'pointer' | 'auto' | 'scroll';
export type EchoTextEase = 'linear' | 'ease-out' | 'ease-in-out' | 'snappy';
export type EchoTextStyle = 'solid' | 'outline';

export interface EchoTextProps {
  /** Text rendered by the crisp front copy and every echo. */
  text?: string;
  /** Number of ghost copies behind the front text, up to 24. */
  echoes?: number;
  /** How slowly deeper echoes catch up, and how far apart they spread along the auto trail. */
  lag?: number;
  /** Entrance spread, cursor lean, drift and burst reach, in px. */
  offset?: number;
  /** Direction the entrance trail settles in from. */
  direction?: EchoTextDirection;
  /** How much of its opacity each echo keeps from the one in front of it. */
  fade?: number;
  /** Blur on the deepest echo, in px. */
  blur?: number;
  /** Color blended into the echoes, stronger toward the back. `false` for plain echoes. */
  tint?: string | false;
  /** Two colors the echoes fade between (nearest → deepest). Replaces the tint when set. */
  echoColors?: [string, string];
  /** Filled or outlined echoes. */
  echoStyle?: EchoTextStyle;
  /** Size of the deepest echo relative to the text. */
  echoScale?: number;
  /** Whether the echoes play on entrance, run the live trail, or both. */
  mode?: EchoTextMode;
  /** What drives the live trail. */
  trail?: EchoTextTrail;
  /** Clicking the text releases a burst of expanding echoes. */
  clickBurst?: boolean;
  /** Distance in px over which the cursor pulls the text to full offset. */
  cursorRadius?: number;
  /** Entrance duration in ms. */
  duration?: number;
  /** Timing curve of the entrance. */
  ease?: EchoTextEase;
  /** Font size of the text. */
  fontSize?: string | number;
  /** Font weight of the text. */
  fontWeight?: string | number;
  /** Color of the front copy. */
  color?: string;
  class?: string;
}

export interface EchoTextVector {
  x: number;
  y: number;
}

export interface EchoTextBurst {
  start: number;
  x: number;
  y: number;
  nodes: HTMLElement[];
}

export interface EchoTextEngineOptions {
  root: HTMLElement;
  burstLayer: HTMLElement | null;
  copies: ReadonlyArray<HTMLElement | null>;
  echoCount: number;
  direction: EchoTextDirection;
  offset: number;
  cursorRadius: number;
  lag: number;
  fade: number;
  blur: number;
  echoScale: number;
  duration: number;
  ease: EchoTextEase;
  mode: EchoTextMode;
  trail: EchoTextTrail;
  clickBurst: boolean;
}
